COPY={lang:{} for lang in LANGUAGES}
for line in DATA.strip().splitlines():
    values=line.split('|')
    if len(values)!=7 or values[0] in COPY['ru'] or not all(values): raise ValueError('Invalid translation row: '+values[0])
    for lang,value in zip(LANGUAGES,values[1:]): COPY[lang][values[0]]=value


def language(request):
    explicit=(request.query_params.get('lang') or '').lower().split('-')[0]
    if explicit in LANGUAGES: request.session['sourcing_lang']=explicit
    return request.session.get('sourcing_lang','ru') if request.session.get('sourcing_lang','ru') in LANGUAGES else 'ru'


def translator(lang):
    return lambda key: COPY[lang][key]


def localize_error(message,lang):
    message=str(message)
    key='error_generic'
    if 'удалены' in message: key='deleted'
    elif 'устарела' in message: key='error_expired'
    elif 'не найдена' in message or 'код доступа неверен' in message or 'Номер или код' in message: key='error_access'
    elif 'позже' in message or 'Слишком много' in message: key='error_limit'
    elif 'изменилась' in message or 'обновите' in message.lower() or 'переход статуса' in message: key='error_conflict'
    return message if lang=='ru' and key=='error_generic' else COPY[lang][key]
